import {objectiveReviewView} from './expedition-objective-review.mjs';
import {ADVENTURES} from './expedition-adventure.mjs';import {GOALS} from './expedition-goal-data.mjs';import {bookProgress,objectiveAssessment} from './expedition-book.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const objectiveMetrics=m=>`通过${m.cleared}/${m.rooms}场 · ${m.alive}/6人生还 · ${m.rounds}回合 · 余药${m.herb}/符${m.rune}/箭${m.arrow}`;
export function objectiveResultView(report){const c=objectiveAssessment(report);if(!c)return '';const goal=GOALS.find(g=>g.id===c.id);return `<section class="objective-result" data-objective-result="${c.id}" data-met="${c.met}"><h3>本次目标：${goal.name} · ${c.met?'条件已达成':'条件未达成'}</h3><p>${goal.rule}</p><p>${objectiveMetrics(c.metrics)}</p>${objectiveReviewView(report)}<small>按本战报当前规则核对。首次记录只在正式领取时写入；实验、试演和任何重演不记达成，也不额外发奖。已记录的目标不会被复战覆盖。</small></section>`;}
export function expeditionBookView(g,selected='all'){
 const p=bookProgress(g),routes=ADVENTURES.filter(a=>selected==='all'||a.id===selected);
 return `<section class="guild-panel expedition-book" data-guild-pane="goals"><p class=eyebrow>单人攻略 / 选目标 → 正式挑战 → 领取后记录 → 继续挑战</p><h2>攻略目标 · ${p.done}/${p.total}</h2><p>复用三个已有基础目标。选择一项目标后，只有本次正式出征满足条件并领取，才保存该项目标的首次方案；没有额外金币、经验或装备。旧通关记录不会被推算为新成就。</p><label>查看路线 <select id="book-route"><option value=all ${selected==='all'?'selected':''}>全部路线</option>${ADVENTURES.map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${a.title}</option>`).join('')}</select></label>${routes.map(a=>{const entry=g.expeditionBook?.[a.id]||{},done=Object.keys(entry).length;return `<details class="book-route" data-book-route="${a.id}" ${routes.length===1?'open':''}><summary>${a.title} · ${done}/3</summary><div class="book-goals">${GOALS.map(goal=>{const proof=entry[goal.id];return `<article data-book-goal="${goal.id}"><h3>${goal.name} · ${proof?'已首次达成':'尚未记录'}</h3><p>${goal.rule}</p>${proof?`<p class=book-proof>第${proof.id}次正式远征 · ${objectiveMetrics(proof.metrics)}</p><div class=bar><button data-goal-report="${a.id}:${goal.id}">重演首次达成战报</button><button data-goal-load="${a.id}:${goal.id}">载入达成方案供调整</button></div>`:''}<button data-goal-prepare="${a.id}:${goal.id}">${proof?'再次挑战':'选择此目标并准备'} →</button></article>`;}).join('')}</div></details>`;}).join('')}<p class=muted>三个标记可能来自不同出征，不表示同一次兼得，也不是最佳或最低成本方案。每项目标最多保留一份首次快照，普通履历超过20次不会删除它。重演使用当前规则；载入方案后仍按当前真实资产、队伍和已应用职责出征，不赠送旧训练/装备、不自动换本人。</p></section>`;
}
